export function getAllQuestions(): Omit<QuestionItem, "id" | "created_at" | "updated_at">[] {
  return [...questionsSRC100, ...questionsSRC300, ...questionsSRC500, ...questionsSRC800];
}

export function getQuestionsByLevel(level: Level): Omit<QuestionItem, "id" | "created_at" | "updated_at">[] {
  switch (level) {
    case 'SRC100':
      return questionsSRC100;
    case 'SRC300':
      return [...questionsSRC100, ...questionsSRC300];
    case 'SRC500':
      return [...questionsSRC100, ...questionsSRC300, ...questionsSRC500];
    case 'SRC800':
      return [...questionsSRC100, ...questionsSRC300, ...questionsSRC500, ...questionsSRC800];
    default:
      return [];
  }
}


export function getCharList(level: Level): string[] {
  const questions = getQuestionsByLevel(level);
  return questions.map(q => q.character);
}

export function getWordList(level: Level): string[] {
  const questions = getQuestionsByLevel(level);
  return questions.map(q => q.word).filter(w => w.length > 1);
}
